import sys

class Shape:
    def area(self):
        raise NotImplementedError

class Rectangle(Shape):
    def __init__(self, length, width):
        self.length = length
        self.width = width
    def area(self):
        return self.length * self.width

class Square(Shape):
    def __init__(self, side):
        self.side = side
    def area(self):
        return self.side * self.side

def to_number(token):
    try:
        return int(token)
    except ValueError:
        return float(token)

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        return
    shape = lines[0].strip().lower()
    tokens = lines[1].split()
    if not tokens:
        return
    if shape == "rectangle":
        if len(tokens) < 2:
            return
        rect = Rectangle(to_number(tokens[0]), to_number(tokens[1]))
        area = rect.area()
    elif shape == "square":
        sq = Square(to_number(tokens[0]))
        area = sq.area()
    else:
        return
    if isinstance(area, float) and area.is_integer():
        area = int(area)
    print(area)

if __name__ == "__main__":
    main()

